CREATE TABLE `deposits` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `clinic_user_id` int(11) DEFAULT NULL,
  `year_month` varchar(7) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `insurer_id` int(11) DEFAULT NULL,
  `insured_name` varchar(255) DEFAULT NULL,
  `therapy_period_start` date DEFAULT NULL,
  `therapy_period_end` date DEFAULT NULL,
  `treatment_type` varchar(255) DEFAULT NULL,
  `treatment_dates` text DEFAULT NULL,
  `total_amount` int(11) DEFAULT NULL,
  `selfpay_amount` int(11) DEFAULT NULL,
  `insurance_billing_amount` int(11) DEFAULT NULL,
  `deposit_amount` int(11) DEFAULT NULL,
  `deposit_date` date DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `deposits_insurers_FK` (`insurer_id`),
  CONSTRAINT `deposits_insurers_FK` FOREIGN KEY (`insurer_id`) REFERENCES `insurers` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=901 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='入金管理';
