--
-- Table structure for table `records`
--

DROP TABLE IF EXISTS `records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `records` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `clinic_user_id` int(11) DEFAULT NULL,
  `date` date NOT NULL,
  `start_time` time DEFAULT NULL,
  `end_time` time DEFAULT NULL,
  `therapy_type` varchar(255) NOT NULL,
  `therapy_category` varchar(255) DEFAULT NULL,
  `insurance_category` varchar(255) DEFAULT NULL,
  `housecall_distance` int(11) DEFAULT NULL,
  `therapy_days` int(11) DEFAULT NULL,
  `consent_expiry` date DEFAULT NULL,
  `therapy_content_id` int(11) DEFAULT NULL,
  `self_fee_id` int(11) DEFAULT NULL,
  `bill_category_id` int(11) DEFAULT NULL,
  `therapist_id` int(11) DEFAULT NULL,
  `abstract` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `records_therapists_FK` (`therapist_id`),
  KEY `records_therapy_conetnt_FK` (`therapy_content_id`),
  KEY `records_bill_categories_FK` (`bill_category_id`),
  KEY `records_clinic_user_id_foreign` (`clinic_user_id`),
  CONSTRAINT `records_bill_categories_FK` FOREIGN KEY (`bill_category_id`) REFERENCES `bill_categories` (`id`),
  CONSTRAINT `records_clinic_user_id_foreign` FOREIGN KEY (`clinic_user_id`) REFERENCES `clinic_users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `records_therapists_FK` FOREIGN KEY (`therapist_id`) REFERENCES `therapists` (`id`),
  CONSTRAINT `records_therapy_conetnt_FK` FOREIGN KEY (`therapy_content_id`) REFERENCES `therapy_contents` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3018 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='実績データ';
/*!40101 SET character_set_client = @saved_cs_client */;

